  "sql": "SELECT md.chembl_id AS compound_chembl_id, cs.canonical_smiles, cr.compound_key, COALESCE(CAST(d.pubmed_id AS TEXT), d.doi) AS pubmed_id_or_doi, a.description AS assay_description, act.standard_type, act.standard_relation, act.standard_value, act.standard_units, NULLIF(act.activity_comment, 'Not Active') AS activity_comment, td.chembl_id AS target_chembl_id, td.pref_name AS target_name, td.organism AS target_organism FROM molecule_dictionary md JOIN activities act ON md.molregno = act.molregno JOIN assays a ON act.assay_id = a.assay_id JOIN target_dictionary td ON a.tid = td.tid JOIN compound_structures cs ON md.molregno = cs.molregno JOIN docs d ON act.doc_id = d.doc_id LEFT JOIN compound_records cr ON act.record_id = cr.record_id WHERE td.pref_name = 'Isocitrate dehydrogenase [NADP] cytoplasmic' AND td.organism = 'Homo sapiens' AND act.standard_type = 'IC50' AND act.standard_units = 'nM' ORDER BY md.chembl_id, cs.canonical_smiles, cr.compound_key, COALESCE(CAST(d.pubmed_id AS TEXT), d.doi), a.description, act.standard_type, act.standard_relation, act.standard_value, act.standard_units, NULLIF(act.activity_comment, 'Not Active'), td.chembl_id, td.pref_name, td.organism"
